import UIKit

class EdgePinner {
    @MainActor
    static func pinEdges(child: UIView, to parent: UIView) {
        child.translatesAutoresizingMaskIntoConstraints = false
        parent.addSubview(child)
        NSLayoutConstraint.activate([
            child.topAnchor.constraint(equalTo: parent.topAnchor),
            child.leadingAnchor.constraint(equalTo: parent.leadingAnchor),
            child.trailingAnchor.constraint(equalTo: parent.trailingAnchor),
            child.bottomAnchor.constraint(equalTo: parent.bottomAnchor)
        ])
    }
}

let root = UIView(frame: CGRect(x: 0, y: 0, width: 200, height: 100))
let childView = UIView()
EdgePinner.pinEdges(child: childView, to: root)
root.layoutIfNeeded()
print("Child size: \(childView.frame.width), \(childView.frame.height)")

import UIKit

class CenterPinner {
    @MainActor
    static func centerInParent(child: UIView, parent: UIView, size: CGSize) {
        child.translatesAutoresizingMaskIntoConstraints = false
        parent.addSubview(child)
        NSLayoutConstraint.activate([
            child.centerXAnchor.constraint(equalTo: parent.centerXAnchor),
            child.centerYAnchor.constraint(equalTo: parent.centerYAnchor),
            child.widthAnchor.constraint(equalToConstant: size.width),
            child.heightAnchor.constraint(equalToConstant: size.height)
        ])
    }
}

let container = UIView(frame: CGRect(x: 0, y: 0, width: 300, height: 300))
let centeredView = UIView()
CenterPinner.centerInParent(child: centeredView, parent: container, size: CGSize(width: 100, height: 80))
container.layoutIfNeeded()
print("Center origin: \(centeredView.frame.origin.x), \(centeredView.frame.origin.y)")

import UIKit

struct PriorityConfigurator {
    @MainActor
    static func configurePriorities(titleLabel: UILabel, badgeLabel: UILabel) {
        titleLabel.setContentHuggingPriority(.defaultLow, for: .horizontal)
        badgeLabel.setContentHuggingPriority(.defaultHigh, for: .horizontal)
    }
}

let tLabel = UILabel()
let bLabel = UILabel()
PriorityConfigurator.configurePriorities(titleLabel: tLabel, badgeLabel: bLabel)
print("Badge priority: \(bLabel.contentHuggingPriority(for: .horizontal).rawValue)")
